'use client'

import * as React from 'react'
import { IconCheck, IconCopy, IconSparkles } from '@tabler/icons-react'
import { AnimatePresence, animate, motion, useMotionValue } from 'motion/react'
import { cn } from '@/lib/utils'

export const DEFAULT_REEL_HANDLES = [
  'adriel',
  'soren',
  'elena',
  'julian',
  'maya',
  'clara',
  'tito',
  'silvan',
  'noor',
  'ravi',
  'yuki',
  'mateo',
  'chloe',
  'lucas',
]

export interface HandleReelProps {
  /** Candidate handles/names displayed during the roll. */
  names?: string[]
  /** Target final handle the reel settles on. @default "ryna" */
  finalName?: string
  /** Static domain or protocol prefix. @default "ryna.me/" */
  prefix?: React.ReactNode
  /** Optional suffix shown after the reel (e.g. ".design"). */
  suffix?: React.ReactNode
  /** Number of visible rows in the viewport. @default 5 */
  rows?: number
  /** Number of full scroll cycles before locking. @default 3 */
  cycles?: number
  /** Duration in seconds of the roll animation. @default 3.8 */
  spinDuration?: number
  /** Accent glow color used on landing. @default "oklch(0.65 0.24 265)" */
  highlightColor?: string
  /** Enable automatic continuous replay loop. @default false */
  loop?: boolean
  /** Delay in milliseconds before replaying when loop is true. @default 2400 */
  loopDelay?: number
  /** External trigger count to trigger spin programmatically. */
  trigger?: number
  /** Show verification badge when handle locks. @default true */
  showVerifiedBadge?: boolean
  /** Enable click-to-copy on the locked handle. @default true */
  copyOnClick?: boolean
  /** Callback fired when the reel settles on the final handle. */
  onLand?: (handle: string) => void
  /** Class name for the outer container. */
  className?: string
  /** Class name for the text typography. */
  textClassName?: string
}

export function HandleReel({
  names = DEFAULT_REEL_HANDLES,
  finalName = 'ryna',
  prefix = 'ryna.me/',
  suffix,
  rows = 5,
  cycles = 3,
  spinDuration = 3.8,
  highlightColor = 'oklch(0.65 0.24 265)',
  loop = false,
  loopDelay = 2400,
  trigger = 0,
  showVerifiedBadge = true,
  copyOnClick = true,
  onLand,
  className,
  textClassName,
}: HandleReelProps) {
  const [internalRun, setInternalRun] = React.useState(0)
  const [rowHeight, setRowHeight] = React.useState(0)
  const [status, setStatus] = React.useState<'idle' | 'spinning' | 'locked'>('spinning')
  const [copied, setCopied] = React.useState(false)

  const y = useMotionValue(0)
  const probeRef = React.useRef<HTMLDivElement>(null)

  const centerIndex = Math.floor(rows / 2)

  // Construct randomized kinetic roll sequence
  const stream = React.useMemo(() => {
    const pool = [...names].sort(() => Math.random() - 0.5)
    const fillerBefore = pool.slice(0, centerIndex)
    const list: string[] = [...fillerBefore, finalName]
    for (let c = 0; c < Math.max(1, cycles); c++) {
      list.push(...[...names].sort(() => Math.random() - 0.5))
    }
    return list
  }, [names, finalName, cycles, centerIndex, internalRun, trigger])

  const targetIndex = centerIndex
  const startIndex = Math.max(targetIndex + 1, stream.length - 1 - centerIndex)
  const viewportHeight = rowHeight * rows

  // Measure exact row height
  React.useLayoutEffect(() => {
    const measured = probeRef.current?.offsetHeight ?? 0
    if (measured && measured !== rowHeight) {
      setRowHeight(measured)
    }
  }, [rowHeight])

  const calcOffset = React.useCallback(
    (idx: number) => viewportHeight / 2 - (idx * rowHeight + rowHeight / 2),
    [viewportHeight, rowHeight],
  )

  // Drive the deceleration spring/momentum
  React.useEffect(() => {
    if (!rowHeight) return
    setStatus('spinning')
    setCopied(false)

    const reducedMotion =
      typeof window !== 'undefined' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches

    if (reducedMotion) {
      y.set(calcOffset(targetIndex))
      setStatus('locked')
      onLand?.(finalName)
      return
    }

    y.set(calcOffset(startIndex))

    let replayTimeout: number | undefined

    const animation = animate(y, calcOffset(targetIndex), {
      duration: spinDuration,
      ease: [0.22, 1, 0.36, 1], // Custom overshoot deceleration curve
      onComplete: () => {
        setStatus('locked')
        onLand?.(finalName)

        if (loop) {
          replayTimeout = window.setTimeout(() => {
            setInternalRun((r) => r + 1)
          }, loopDelay)
        }
      },
    })

    return () => {
      animation.stop()
      if (replayTimeout) window.clearTimeout(replayTimeout)
    }
  }, [
    rowHeight,
    internalRun,
    trigger,
    startIndex,
    targetIndex,
    spinDuration,
    loop,
    loopDelay,
    calcOffset,
    finalName,
    onLand,
    y,
  ])

  const handleCopy = () => {
    if (!copyOnClick || status !== 'locked') return
    const textToCopy = `https://${typeof prefix === 'string' ? prefix : ''}${finalName}${
      typeof suffix === 'string' ? suffix : ''
    }`
    navigator.clipboard.writeText(textToCopy).then(() => {
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    })
  }

  return (
    <div
      role="region"
      aria-label="Kinetic handle picker"
      className={cn(
        'relative flex w-full items-center justify-center select-none py-8 px-4',
        className,
      )}
    >
      <div
        onClick={handleCopy}
        className={cn(
          'group relative inline-flex items-center gap-2 rounded-3xl border border-border/50 bg-card/60 px-6 py-4 backdrop-blur-xl shadow-md transition-all',
          copyOnClick && status === 'locked' && 'cursor-pointer hover:border-primary/50 hover:shadow-lg',
        )}
      >
        {/* Domain Prefix Pill */}
        <div className="flex shrink-0 items-center gap-1.5 rounded-xl border border-border/60 bg-muted/70 px-3 py-1.5 text-base sm:text-2xl font-semibold tracking-tight text-foreground/80">
          <IconSparkles className="size-4 text-primary" />
          <span>{prefix}</span>
        </div>

        {/* Tumbler Reel Viewport */}
        <div
          className={cn(
            'relative overflow-hidden text-2xl sm:text-4xl font-bold tracking-tight text-foreground',
            textClassName,
          )}
          style={{ height: viewportHeight || 56 }}
        >
          {/* Probe for measuring line height */}
          <div
            ref={probeRef}
            aria-hidden="true"
            className="pointer-events-none invisible absolute whitespace-nowrap leading-[1.3]"
          >
            {finalName}
          </div>

          {/* Scrolling column */}
          <motion.div
            style={{ y }}
            className={cn('transform-gpu will-change-transform', !rowHeight && 'opacity-0')}
          >
            {stream.map((item, idx) => {
              const isTarget = idx === targetIndex
              return (
                <div
                  key={idx}
                  className={cn(
                    'whitespace-nowrap leading-[1.3] transition-all duration-300',
                    isTarget && status === 'locked'
                      ? 'text-primary drop-shadow-[0_0_12px_rgba(99,102,241,0.3)]'
                      : isTarget
                        ? 'text-foreground'
                        : 'text-muted-foreground/30',
                  )}
                >
                  {item}
                </div>
              )
            })}
          </motion.div>

          {/* Top and Bottom Optical Vignette Masks */}
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-x-0 top-0 h-10 bg-gradient-to-b from-card via-card/80 to-transparent"
          />
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-x-0 bottom-0 h-10 bg-gradient-to-t from-card via-card/80 to-transparent"
          />
        </div>

        {suffix && (
          <span className="shrink-0 text-xl sm:text-2xl font-medium text-muted-foreground">
            {suffix}
          </span>
        )}

        {/* Tactile Center Target Viewfinder Frame */}
        <div
          aria-hidden="true"
          className={cn(
            'pointer-events-none absolute inset-x-2 rounded-2xl border transition-all duration-500',
            status === 'locked'
              ? 'border-primary/40 bg-primary/[0.03] shadow-[0_0_24px_-4px_rgba(99,102,241,0.25)]'
              : 'border-border/30 bg-muted/5',
          )}
          style={{
            top: centerIndex * rowHeight + 8,
            height: (rowHeight || 56) + 16,
          }}
        />

        {/* Animated Verified / Copied Pill Badge */}
        <AnimatePresence>
          {status === 'locked' && showVerifiedBadge && (
            <motion.div
              initial={{ opacity: 0, scale: 0.8, x: -8 }}
              animate={{ opacity: 1, scale: 1, x: 0 }}
              exit={{ opacity: 0, scale: 0.8 }}
              transition={{ type: 'spring', stiffness: 350, damping: 25 }}
              className="ml-2 hidden sm:flex items-center gap-1.5 rounded-full border border-emerald-500/30 bg-emerald-500/10 px-2.5 py-1 text-xs font-semibold text-emerald-600 dark:text-emerald-400"
            >
              {copied ? (
                <>
                  <IconCheck className="size-3.5 text-emerald-500" />
                  <span>Copied!</span>
                </>
              ) : (
                <>
                  <IconCheck className="size-3.5 text-emerald-500" />
                  <span>Available</span>
                </>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  )
}
